sql.where:
R.DEL_DT IS NULL

	AND R.LRN_STTS_CD = #{lrnSttsCd}


	AND R.PRGRM_TYPE_CD = #{prgrmTypeCd}


	AND R.RSVT_YMD >= #{startRsvtYmd}


	AND R.RSVT_YMD <= #{endRsvtYmd}




			AND R.RSVT_NO LIKE CONCAT('%', #{searchKeyword}, '%')


			AND R.SCHL_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND R.PIC_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND R.PIC_TELNO LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (
				R.RSVT_NO LIKE CONCAT('%', #{searchKeyword}, '%')
				OR R.SCHL_NM LIKE CONCAT('%', #{searchKeyword}, '%')
				OR R.PIC_NM LIKE CONCAT('%', #{searchKeyword}, '%')
				OR R.PIC_TELNO LIKE CONCAT('%', #{searchKeyword}, '%')
			)

mapper.select:
SELECT
FROM EDU_RSVT_MST R LEFT JOIN EDU_PRGRM_MST P ON P.PRGRM_SN = R.PRGRM_SN AND P.PRGRM_TYPE_CD = R.PRGRM_TYPE_CD
ORDER BY R.RSVT_YMD DESC, R.VST_HM DESC, R.RSVT_SN DESC LIMIT #{offset}, #{limit}
